import{_ as a,C as r,o as e,c as l,a4 as d,E as i}from"./chunks/framework.DAD9IEko.js";const m=JSON.parse('{"title":"路径13: 无位置传感器控制","description":"","frontmatter":{"date":"2026-06-04T00:00:00.000Z","section":"电机控制","chapter":"practice","chapterTitle":"工程实践","chapterOrder":20,"category":"工程实践","source":"motor","visibility":"public","title":"路径13: 无位置传感器控制","tags":["motor-control"],"status":"learning","summary":"> 来源：手把手 Part 8-10 + 主动磁链 + SR-CKF | 前置：路径12站1-3 | 难度：~","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/practice/PRACTICE-13-Sensorless-Control.md","filePath":"content/motor/practice/PRACTICE-13-Sensorless-Control.md","lastUpdated":1783181958000}'),s={name:"content/motor/practice/PRACTICE-13-Sensorless-Control.md"};function n(h,t,c,u,_,A){const o=r("MermaidDiagram");return e(),l("div",null,[t[0]||(t[0]=d('<h1 id="路径13-无位置传感器控制" tabindex="-1">路径13: 无位置传感器控制 <a class="header-anchor" href="#路径13-无位置传感器控制" aria-label="Permalink to &quot;路径13: 无位置传感器控制&quot;">​</a></h1><blockquote><p>来源：手把手 Part 8-10 + 主动磁链 + SR-CKF | 前置：路径12站1-3 | 难度：~</p></blockquote><h2 id="_1-路径概述" tabindex="-1">1. 路径概述 <a class="header-anchor" href="#_1-路径概述" aria-label="Permalink to &quot;1. 路径概述&quot;">​</a></h2><p>5种无位置传感器控制方法的原理与仿真验证，从中高速到零低速全覆盖。适合已掌握有感FOC和基础仿真的学习者，系统理解无感控制的方法论和工程实现要点。</p><p><strong>前置知识：</strong> 路径12站1-3（双闭环FOC、电流环/速度环参数设计） <strong>学习目标：</strong> 理解5种无位置传感器控制方法的原理差异、适用转速范围和工程实现要点</p><h2 id="_2-学习路径图" tabindex="-1">2. 学习路径图 <a class="header-anchor" href="#_2-学习路径图" aria-label="Permalink to &quot;2. 学习路径图&quot;">​</a></h2>',6)),i(o,{code:"graph%20LR%0A%20%20%20%20A%5B%E7%AB%991%3A%20MRAS%5D%20--%3E%20B%5B%E7%AB%992%3A%20SMO%5D%0A%20%20%20%20B%20--%3E%20C%5B%E7%AB%993%3A%20HFI%5D%0A%20%20%20%20A%20--%3E%20D%5B%E7%AB%994%3A%20%E4%B8%BB%E5%8A%A8%E7%A3%81%E9%93%BE%5D%0A%20%20%20%20B%20--%3E%20D%0A%20%20%20%20D%20--%3E%20E%5B%E7%AB%995%3A%20SR-CKF%5D%0A"}),t[1]||(t[1]=d('<h2 id="_3-站点详情表" tabindex="-1">3. 站点详情表 <a class="header-anchor" href="#_3-站点详情表" aria-label="Permalink to &quot;3. 站点详情表&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>站号</th><th>主题</th><th>资源引用</th><th>交叉引用KB模块</th><th>难度</th><th>预计学习时间</th></tr></thead><tbody><tr><td>站1</td><td>MRAS模型参考自适应</td><td><code>第8部分.zip</code>.zip) chenshamotor</td><td>ALG-07(无感观测器)</td><td></td><td>4-5小时</td></tr><tr><td>站2</td><td>SMO滑模观测器</td><td><code>第9部分(已解压)</code>/) — 含完整PDF/仿真/12篇论文</td><td>ALG-07(无感观测器)</td><td></td><td>6-8小时</td></tr><tr><td>站3</td><td>HFI高频注入</td><td><code>第10部分.zip</code> chenshamotor</td><td>ALG-09(高频注入)</td><td></td><td>5-6小时</td></tr><tr><td>站4</td><td>主动磁链观测器</td><td><code>active_flux.slx</code> + <code>active_flux.c</code> + <code>active_flux.h</code> 不完善</td><td>ALG-07(无感观测器)</td><td></td><td>4-5小时</td></tr><tr><td>站5</td><td>SR-CKF无位置传感器</td><td><code>SR_CKF.m</code> — 680行完整MATLAB脚本 不完善</td><td>ALG-07(无感观测器), CT-13(LQR/LQG)</td><td></td><td>5-6小时</td></tr></tbody></table></div><h2 id="_4-各站详细说明" tabindex="-1">4. 各站详细说明 <a class="header-anchor" href="#_4-各站详细说明" aria-label="Permalink to &quot;4. 各站详细说明&quot;">​</a></h2><h3 id="站1-mras模型参考自适应" tabindex="-1">站1: MRAS模型参考自适应 <a class="header-anchor" href="#站1-mras模型参考自适应" aria-label="Permalink to &quot;站1: MRAS模型参考自适应&quot;">​</a></h3><ul><li><strong>核心要点：</strong> MRAS基本原理（参考模型vs可调模型）、自适应律设计、Lyapunov稳定性证明</li><li><strong>资源使用方法：</strong> 解压zip后按教程顺序操作</li><li><strong>学习建议：</strong> MRAS是最经典的无感方法之一，适合作为无感控制的入门方法。对照KB模块ALG-07(无感观测器)中的MRAS章节</li></ul><h3 id="站2-smo滑模观测器-核心站-内容最完整" tabindex="-1">站2: SMO滑模观测器（核心站，内容最完整） <a class="header-anchor" href="#站2-smo滑模观测器-核心站-内容最完整" aria-label="Permalink to &quot;站2: SMO滑模观测器（核心站，内容最完整）&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 反EMF滑模观测器原理、锁相环(PLL)角度提取、抖振抑制、PI参数整定</li><li><strong>资源使用方法：</strong> 本站已解压，可直接访问： <ul><li><code>滑模观测器无位置控制资料介绍.pdf</code>/滑模观测器无位置控制资料介绍.pdf)</li><li><code>SMO仿真</code>/SMO仿真/) — Pmsm_smo_actan2.mdl</li><li><code>仿真搭建过程</code>/仿真搭建过程介绍/) — SVPWM和滑模部分搭建教程PDF</li><li><code>原理推导</code>/原理推导和笔算解释/) — 反正切函数和角度校正公式推导</li><li><code>参数调试</code>/滑模观测器和Pi调节器参数调试过程/) — PI整定理论和实际计算参数</li><li><code>波形分析</code>/波形记录及其简要分析/) — 三相电流/位置/转速/转矩波形</li><li><code>参考论文</code>/参考论文/) — 12篇中文学术论文</li></ul></li><li><strong>学习建议：</strong> 这是5种无感方法中资料最完整的一站，建议作为重点深入学习。先读资料介绍PDF建立框架，再看仿真搭建教程，最后运行仿真验证</li></ul><h3 id="站3-hfi高频注入" tabindex="-1">站3: HFI高频注入 <a class="header-anchor" href="#站3-hfi高频注入" aria-label="Permalink to &quot;站3: HFI高频注入&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 凸极效应利用、脉振注入vs方波注入、N/S极极性判断、零低速区域角度估计</li><li><strong>资源使用方法：</strong> 解压zip后按教程操作</li><li><strong>学习建议：</strong> HFI是唯一能在零低速区域工作的无感方法，通常与SMO/MRAS配合实现全速域无感控制。对照KB模块ALG-09(高频注入)</li></ul><h3 id="站4-主动磁链观测器-不完善" tabindex="-1">站4: 主动磁链观测器 不完善 <a class="header-anchor" href="#站4-主动磁链观测器-不完善" aria-label="Permalink to &quot;站4: 主动磁链观测器  不完善&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 主动磁链概念、IPMSM凸极信息利用、从仿真到C代码的完整实现</li><li><strong>资源使用方法：</strong> 打开active_flux.slx运行仿真，对照active_flux.c/h理解嵌入式实现</li><li><strong>学习建议：</strong> 这是唯一同时提供Simulink模型和嵌入式C代码的无感方法，是理解&quot;仿真→代码&quot;落地的绝佳案例。C代码使用ARM CMSIS-DSP库(arm_cos_f32/arm_sin_f32)。 资源不完善，建议对照ALG-07(无感观测器)和ALG-16(非线性磁链观测器)补充学习</li></ul><h3 id="站5-sr-ckf无位置传感器-不完善" tabindex="-1">站5: SR-CKF无位置传感器 不完善 <a class="header-anchor" href="#站5-sr-ckf无位置传感器-不完善" aria-label="Permalink to &quot;站5: SR-CKF无位置传感器  不完善&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 平方根容积卡尔曼滤波(SR-CKF)原理、状态方程建模、噪声协方差矩阵设计、数值稳定性</li><li><strong>资源使用方法：</strong> 直接运行SR_CKF.m（680行完整脚本，注释详尽，无需额外文件）</li><li><strong>学习建议：</strong> SR-CKF是最高端的无感方法，计算量大但精度最高。 资源不完善——仿真中未考虑逆变器非线性、参数耦合等工程难点，实际硬件效果与仿真差距较大，建议对照ALG-21(参数辨识)理解在线辨识的工程局限</li></ul><h2 id="_5-路径间关联" tabindex="-1">5. 路径间关联 <a class="header-anchor" href="#_5-路径间关联" aria-label="Permalink to &quot;5. 路径间关联&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>关联路径</th><th>关系</th><th>说明</th></tr></thead><tbody><tr><td>路径12(PMSM仿真)</td><td>前置</td><td>学完站12-3后可开始本路径</td></tr><tr><td>路径14(工程实现)</td><td>后续</td><td>站4的C代码和站2的参数调试可直接用于路径14</td></tr><tr><td>路径9(C仿真)</td><td>替代</td><td>无MATLAB许可证时可用C仿真验证SMO/MRAS</td></tr><tr><td>路径11(FOC仿真)</td><td>基础</td><td>站11-6的PLL是本路径多种方法的角度提取基础</td></tr></tbody></table></div><h3 id="_5种无感方法对比" tabindex="-1">5种无感方法对比 <a class="header-anchor" href="#_5种无感方法对比" aria-label="Permalink to &quot;5种无感方法对比&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>方法</th><th>适用转速范围</th><th>计算复杂度</th><th>精度</th><th>工程难度</th><th>典型应用</th></tr></thead><tbody><tr><td>MRAS</td><td>中高速</td><td>低</td><td>中</td><td>低</td><td>家电变频器</td></tr><tr><td>SMO</td><td>中高速</td><td>中</td><td>中高</td><td>中</td><td>工业伺服</td></tr><tr><td>HFI</td><td>零低速</td><td>中</td><td>高</td><td>高</td><td>电动汽车</td></tr><tr><td>主动磁链</td><td>中高速(IPMSM)</td><td>中</td><td>高</td><td>中</td><td>内置式PMSM驱动</td></tr><tr><td>SR-CKF</td><td>全速域</td><td>高</td><td>最高</td><td>高</td><td>高精度伺服</td></tr></tbody></table></div><h2 id="_6-补充资源" tabindex="-1">6. 补充资源 <a class="header-anchor" href="#_6-补充资源" aria-label="Permalink to &quot;6. 补充资源&quot;">​</a></h2><ul><li><code>foc_smo_luenberger_2020.slx</code> — FOC+SMO+龙伯格观测器对比模型</li><li><code>motor_smo.slx</code> — 电机+滑模观测器模型</li><li><a href="./../simulation/SIM-00-C-Simulation-Overview.html">C仿真替代方案</a> — 无MATLAB许可证时使用路径9的C仿真平台</li><li><code>教材3: 阮毅/陈伯时《电力拖动自动控制系统》</code> chenshamotor</li></ul><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to &quot;7. 常见问题&quot;">​</a></h2><p><strong>Q: 5种方法如何选择？</strong> A: 取决于应用场景——MRAS适合低成本家电、SMO适合工业通用、HFI适合需要零低速启动的场景、主动磁链适合IPMSM、SR-CKF适合高精度需求。实际工程中常采用HFI+SMO的混合方案实现全速域无感。</p><p><strong>Q: 站2的解压目录结构是什么？</strong> A: 解压后首层目录包含：SMO仿真/、仿真搭建过程介绍/、原理推导和笔算解释/、基本参数说明/、波形记录及其简要分析/、滑模观测器和Pi调节器参数调试过程/、参考论文/。建议先读&quot;滑模观测器无位置控制资料介绍.pdf&quot;建立全局认知。</p><p><strong>Q: 站5的SR_CKF.m如何运行？</strong> A: 直接在MATLAB中打开运行即可，脚本包含完整的电机模型和可视化，无需额外文件。脚本约680行，注释详尽，建议逐段阅读理解。</p><p><strong>注意事项：</strong> zip压缩包解压密码统一为 <code>chenshamotor</code>。资源为中文。资源位置可能变化，请以实际路径为准。</p>',24))])}const b=a(s,[["render",n]]);export{m as __pageData,b as default};
